                row[sum_column], row_number, sum_column
            )
        if avg_column is not None:
            state["avg_total"] = Decimal(state["avg_total"]) + parse_decimal(
                row[avg_column], row_number, avg_column
            )
            state["avg_count"] = int(state["avg_count"]) + 1

